local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds

local Text = CS.UnityEngine.UI.Text
local Image = CS.UnityEngine.UI.Image
local ImageAlterable = CS.Engine.UI.ImageAlterable
local Button = CS.UnityEngine.UI.Button

local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule

---@class UIFeelingCallDialog
local UIFeelingCallDialog = Class("UIFeelingCallDialog")

function UIFeelingCallDialog:__init() 
    self._catId = nil              --角色id
    self._talkCountId = nil        --通话id
    self._catVo = nil

    self._telephoneIds = {}        --该次通话所有的对话
    self._co = nil  
    self.isAutoPlay = true         --是否自动播放
end

function UIFeelingCallDialog:__delete()
    self._catId = nil              --角色id
    self._talkCountId = nil        --通话id
    self._catVo = nil

    self._telephoneIds = {}        --该次通话所有的对话
    self._co = nil  
    self.isAutoPlay = true         --是否自动播放
end

function UIFeelingCallDialog:Awake()
    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._talkCountId = checkNumber(argument.talkCountId)  -- 
    local vo = PhoneUtils.GetPhoneTalkContentVo(self._talkCountId)
    if not vo then
        return
    end
    self._catId = checkNumber(vo.character)  --
    self._catVo = PhoneUtils.GetCatVo(self._catId)
    if not self._catVo then 
        return
    end
    
    self:FillSelf()
end

function UIFeelingCallDialog:FillSelf()
    SetButtonAction(self.BtnAuto, Bind(self, self.OnBtnAuto))
    SetButtonAction(self.BtnAnswer, Bind(self, self.OnBtnAnswer))
    SetButtonAction(self.BtnHangup, Bind(self, self.OnBtnHangup))

    CfUtils.FillText(self.TxtState, localize("邀请你语音通话"))
    CfUtils.FillText(self.TxtName, self._catVo.name)
    local skinCardId = PhoneUtils.GetRoleCurCardSkinId(self._catId)
    CfUtils.FillImage(self.IconRole, CardConfMgr:GetInstance():GetCardDefaultBodyIconPath(skinCardId), true)
end

--接听
function UIFeelingCallDialog:OnBtnAnswer()
    KTool.SetActive(self.Calling, true)
    CfUtils.FillText(self.TxtState, localize("语音通话中..."))
    self._telephoneIds = PhoneUtils.GetTalkIds(self._talkCountId)
    if self._telephoneIds and table.count(self._telephoneIds) > 0 then
        self._co = cs_coroutine.start(self.PlayChating, self)
    end
end

--开始打电话的协程
function UIFeelingCallDialog:PlayChating()
    if not self._telephoneIds then
        return
    end
    if self.isAutoPlay then
        for i = 1, #self._telephoneIds do
            local vo = PhoneUtils.GetPhoneTelephoneVo(self._telephoneIds[i])
            if vo then
                CfUtils.FillText(self.TxtDialogue, vo.text)
            end
            coroutine.yield(WaitForSeconds(2))
        end
    end
end

--自动播放
function UIFeelingCallDialog:OnBtnAuto()
    self.isAutoPlay = not self.isAutoPlay
    KTool.SetActive(self.BtnAuto.transform:Find("Text"), not self.isAutoPlay)
    
end

--挂断
function UIFeelingCallDialog:OnBtnHangup()
    UIModule.CloseDialog(self.controller)
end

function UIFeelingCallDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
    end))
    return coWait
end

function UIFeelingCallDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self) then
            if self._co then 
                cs_coroutine.stop(self._co)
                self._co = nil
            end
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFeelingCallDialog
